def book_allocation(pages: list[int], m: int) -> int:
    if m > len(pages):
        return -1

    def students(cap: int) -> int:
        cnt, cur = 1, 0
        for p in pages:
            if cur + p > cap:
                cnt += 1
                cur = 0
            cur += p
        return cnt

    lo, hi = max(pages), sum(pages)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if students(mid) <= m:
            hi = mid
        else:
            lo = mid + 1
    return lo
